DROP TABLE IF EXISTS `notulen`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notulen` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `judul` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hari_tanggal` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `waktu` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tempat` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `dasar` text COLLATE utf8mb4_unicode_ci,
  `narasumber` text COLLATE utf8mb4_unicode_ci,
  `peserta_deskripsi` text COLLATE utf8mb4_unicode_ci,
  `peserta_daftar` text COLLATE utf8mb4_unicode_ci,
  `hasil_acara` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `penutup` text COLLATE utf8mb4_unicode_ci,
  `tanggal_naskah` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `atasan_user_id` bigint unsigned DEFAULT NULL,
  `atasan_nama` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `atasan_nip` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `atasan_jabatan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pelapor_user_id` bigint unsigned DEFAULT NULL,
  `pelapor_nama` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pelapor_nip` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pelapor_jabatan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dibuat_oleh` bigint unsigned DEFAULT NULL,
  `dibuat_oleh_nama` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=105 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

