/*!40000 ALTER TABLE `notulen` DISABLE KEYS */;
INSERT INTO `notulen` VALUES (7,'Rapat Koordinasi Penyusunan SOP (Standar Operasional Prosedur) Perizinan Terintegrasi','Selasa, 6 Oktober 2026','13.00 WIB – Selesai','Ruang Rapat Kolaborasi, Gd. Moch Ichsan Lt. 4 Sekretariat Daerah Kota Semarang ','Surat Undangan DPMPTSP no. 1178/005/IX/2026',NULL,NULL,NULL,'<h3><strong>Poin-Poin Pembahasan</strong></h3><ol start=\"1\"><li><p><strong>Ketentuan Umum dan Masukan Bagian Organisasi</strong></p><ul><li><p>Seluruh SOP perizinan terintegrasi wajib berpedoman pada ketentuan Peraturan Pemerintah Nomor 28 Tahun 2025.</p></li><li><p>Draft dokumen SOP dari dinas teknis (Dinas Koperasi, Dinas Ketapang, Dinas Pertanian) harus sudah dalam kondisi final (<em>fix</em>) sebelum diajukan ke tahap legalisasi.</p></li><li><p>Setiap penyusunan SOP wajib mengidentifikasi dan mencantumkan keterkaitan dengan SOP lain yang relevan di lingkungan pemerintah daerah.</p></li><li><p>Dokumen pendukung wajib menyertakan bagan/tabel komparasi alur proses (<em>before-after</em>) guna melihat efisiensi tahapan perizinan.</p></li><li><p>Peletakan kolom paraf pimpinan OPD diletakkan pada posisi <strong>bawah kanan</strong> pada lembar pengajuan draft SOP.</p></li></ul></li><li><p>Ketetapan Waktu Layanan (SLA)</p><ul><li><p>Penetapan waktu penyelesaian layanan harus taat asas dan merujuk ketetapan regulasi SLA yang berlaku; OPD tidak diperkenankan menetapkan estimasi waktu sendiri secara sepihak.</p></li><li><p>Menanggapi pembahasan SLA penerbitan SK 3 Koperasi (standar 3 hari kerja), Dinas Koperasi dan DPMPTSP mengkaji opsi kemungkinan perpanjangan waktu SLA dalam kondisi khusus. Hal ini akan diselaraskan kembali dengan regulasi teknis pengampu agar tidak melanggar ketentuan batas waktu pelayanan.</p></li></ul></li><li><p>Mekanisme Antar-OPD dan Berita Acara</p><ul><li><p>Pelaksanaan SOP yang melibatkan lintas sektoral (misalnya kolaborasi dua OPD antara dinas teknis dan DPMPTSP) wajib menyusun <strong>Berita Acara Kesepakatan</strong>.</p></li><li><p>Berita Acara tersebut memuat klausul persetujuan bersama serta komitmen tindak lanjut pembuatan SOP terintegrasi.</p></li><li><p>Paraf persetujuan pada draf SOP dilakukan oleh kepala OPD pemohon/pengaju terkait.</p></li></ul></li><li><p>Kewenangan Pengesahan dan Penandatanganan</p><ol start=\"1\"><li><p>Untuk dokumen operasional berbasis Tim Teknis, legalisasi SK Tim cukup ditandatangani oleh <strong>Ketua Tim</strong>.</p></li><li><p>Mekanisme pengesahan dokumen SOP:</p><ul><li><p>Apabila payung hukum Peraturan Wali Kota (Perwal) SOP telah ditetapkan dan mendelegasikan wewenang, maka dokumen cukup ditandatangani oleh <strong>Sekretaris Daerah (Sekda)</strong>.</p></li><li><p>Apabila belum didelegasikan melalui Perwal, pengesahan dokumen SOP wajib ditandatangani langsung oleh <strong>Wali Kota</strong>.</p></li></ul></li></ol></li></ol><h3><strong>Tindak Lanjut</strong></h3><ol start=\"1\"><li><p>Dinas Koperasi, Dinas Ketapang, dan Dinas Pertanian menyelesaikan perbaikan draf SOP teknis, tabel <em>before-after</em>, serta matriks keterkaitan SOP paling lambat [Tanggal/Bulan].</p></li><li><p>Penyusunan dan penandatanganan Berita Acara persetujuan antar-OPD yang terlibat dalam perizinan terintegrasi.</p></li><li><p>Penyerahan draf final yang telah dibubuhi paraf pimpinan OPD di posisi kanan bawah kepada Bagian Organisasi untuk verifikasi akhir sebelum diajukan ke proses pengesahan.</p></li></ol><p></p>','Demikian Notulen ini dibuat untuk menjadikan periksa.','Semarang, 7 Oktober 2026',48,'Milatina, S.Kom, M. Kom','198510152006042005','Kepala Sub Bagian Umum dan Kepegawaian\nDPMPTSP Kota Semarang',32,'Riyanto Nugroho, A.Md.Kom','199303252025061002','Pranata Sumber Daya Manusia Aparatur Terampil\nDPMPTSP Kota Semarang',32,'Riyanto Nugroho, A.Md.Kom','2026-10-07 10:10:49','2026-10-07 10:26:18');
/*!40000 ALTER TABLE `notulen` ENABLE KEYS */;
UNLOCK TABLES;

