CREATE TABLE `pegawai_riwayat_cpns` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nip` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `file_field_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
