  `jabatan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kd_golongan` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `masa_kerja_bulan` int unsigned DEFAULT NULL,
  `masa_kerja_tahun` int unsigned DEFAULT NULL,
  `nomor_sk` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_sk` date DEFAULT NULL,
  `tmt_sk` date DEFAULT NULL,
  `unit_kerja` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pegawai_riwayat_cpns_nip_unique` (`nip`)
) ENGINE=InnoDB AUTO_INCREMENT=68 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
