--
-- Table structure for table `pegawai_riwayat_jabatan`
--

DROP TABLE IF EXISTS `pegawai_riwayat_jabatan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pegawai_riwayat_jabatan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nip` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `no_urut` int unsigned DEFAULT NULL,
  `file_jabatan_url` text COLLATE utf8mb4_unicode_ci,
  `jabatan_baru` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jenis_jabatan` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nomor_sk_jabatan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `opd` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_sk_jabatan` date DEFAULT NULL,
  `tmt_sk_jabatan` date DEFAULT NULL,
  `unit_kerja` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `verifikasi` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pegawai_riwayat_jabatan_nip_index` (`nip`)
) ENGINE=InnoDB AUTO_INCREMENT=314 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

