CREATE TABLE `pegawai_riwayat_pangkat` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nip` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `no_urut` int unsigned DEFAULT NULL,
  `file_pangkat_url` text COLLATE utf8mb4_unicode_ci,
  `golongan` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jenis_kenaikan_pangkat` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `masa_kerja_bulan` int unsigned DEFAULT NULL,
  `masa_kerja_tahun` int unsigned DEFAULT NULL,
  `nomor_sk_pangkat` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pangkat` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `siasn` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tanggal_sk_pangkat` date DEFAULT NULL,
  `tmt_sk_pangkat` date DEFAULT NULL,
  `verifikasi` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pegawai_riwayat_pangkat_nip_index` (`nip`)
) ENGINE=InnoDB AUTO_INCREMENT=115 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
