INSERT INTO `surat_tugas` VALUES (4,'Penyerahan SK Kenaikan Pangkat PNS periode 1 Oktober 2026 dalam Lingkungan Pemerintah Kota Semarang','Rabu, 30 September 2026','13.00 s.d selesai','Bidang Pengembangan Pegawai BKPP Gd. Moh Ihsan Lantai 5 ','Semarang, 29 September 2026','Peraturan Daerah Kota Semarang Nomor 13 Tahun 2025 tentang Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2026\nPeraturan  Wali  Kota  Semarang  Nomor  61  Tahun  2025 tentang  Penjabaran  Anggaran  Pendapatan  dan  Belanja Daerah Tahun Anggaran 2026','Surat BKPP No. B/800/185/IX/2026 perihal Penyerahan SK Kenaikan Pangkat PNS periode 1 Oktober 2026 di Lingkungan Pemerintah Kota Semarang',32,'Riyanto Nugroho, A.Md.Kom','2026-10-01 07:09:52','2026-10-01 08:32:41'),(24,'Rapat Koordinasi Penyusunan SOP (Standar Operasional Prosedur) Perizinan Terintegrasi','Selasa, 6 Oktober 2026','13.00 WIB s.d. selesai','Ruang Rapat Kolaborasi Gd. Moch Ichsan Kota Semarang',NULL,'Peraturan Daerah Kota Semarang Nomor 13 Tahun 2025 tentang Anggaran Pendapatan dan Belanja Daerah Tahun Anggaran 2026\nPeraturan  Wali  Kota  Semarang  Nomor  61  Tahun  2025 tentang  Penjabaran  Anggaran  Pendapatan  dan  Belanja Daerah Tahun Anggaran 2026','Surat Undangan Dinas Penanaman Modal dan Pelayanan Terpadu Satu Pintu Kota Semarang no 1178/005/IX/2026 ',32,'Riyanto Nugroho, A.Md.Kom','2026-10-06 11:29:48','2026-10-06 14:26:30');
